		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{
				Description					= "Validation harness: dumps every QI_* module value per bar to CSV. Not for trading use.";
				Name						= "QI_EgvDump";
				Calculate					= Calculate.OnBarClose;
				IsOverlay					= true;
				DisplayInDataBox			= false;
				IsSuspendedWhileInactive	= true;
				OutputFolder				= @"C:\Users\rajib\OneDrive\Documents\ninjatrader_quant_indicators\validation\runs";
			}
			else if (State == State.Configure)
			{
				// Hosted QI_IBS adds its own daily series; nothing to do here.
			}
			else if (State == State.DataLoaded)
			{
				atrregime = CacheIndicator<QI_ATRRegime>(new QI_ATRRegime() { Threshold = 1.5, ShowDisclaimer = false }, Input, ref atrregimeCache);
				bollingerpctb = CacheIndicator<QI_BollingerPctB>(new QI_BollingerPctB() { LowerThreshold = -100, UpperThreshold = 100, ShowDisclaimer = false }, Input, ref bollingerpctbCache);
				chopindex = CacheIndicator<QI_ChopIndex>(new QI_ChopIndex() { LowerThreshold = 38.2, UpperThreshold = 61.8, ShowStateText = true, ShowDisclaimer = false }, Input, ref chopindexCache);
				compositevol = CacheIndicator<QI_CompositeVol>(new QI_CompositeVol() { LowerThreshold = -1.5, UpperThreshold = 1.5, ShowDisclaimer = false }, Input, ref compositevolCache);
				connorsrsi = CacheIndicator<QI_ConnorsRSI>(new QI_ConnorsRSI() { LowerThreshold = 15, UpperThreshold = 85, ShowDisclaimer = false }, Input, ref connorsrsiCache);
				consecdays = CacheIndicator<QI_ConsecDays>(new QI_ConsecDays() { LowerThreshold = -3, UpperThreshold = 3, ShowDisclaimer = false }, Input, ref consecdaysCache);
				emacross = CacheIndicator<QI_EMACross>(new QI_EMACross() { ShowDisclaimer = false }, Input, ref emacrossCache);
				hedgingpressure = CacheIndicator<QI_HedgingPressure>(new QI_HedgingPressure() { LowerThreshold = -35, UpperThreshold = 35, ShowHpLines = true, ShowDisclaimer = false }, Input, ref hedgingpressureCache);
				ibs = CacheIndicator<QI_IBS>(new QI_IBS() { LowerThreshold = 0.20, UpperThreshold = 0.80, ShowDisclaimer = false }, Input, ref ibsCache);
				keylevels = CacheIndicator<QI_KeyLevels>(new QI_KeyLevels() { ShowPrevDayLevels = true, ShowMonthlyLevels = true, ShowOrbLevels = true, ShowAsianSessionLevels = true, ShowDisclaimer = false }, Input, ref keylevelsCache);
				liquiditysweep = CacheIndicator<QI_LiquiditySweep>(new QI_LiquiditySweep() { SwingLookback = 20, SweepWickMultiple = 2.0, SweepVolMultiple = 1.5, EqualLevelTolerance = 0.05, ConsolidationAtrRatio = 0.6, UsePrevDayLevels = true, UseMonthlyLevels = true, UseOrbLevels = true, TextOffsetTicks = 15, SignalFontSize = 13, DuplicateBarWindow = 5, ShowDisclaimer = false }, Input, ref liquiditysweepCache);
				macdhistogram = CacheIndicator<QI_MACDHistogram>(new QI_MACDHistogram() { Threshold = 0, ShowDisclaimer = false }, Input, ref macdhistogramCache);
				orderflowplus = CacheIndicator<QI_OrderFlowPlus>(new QI_OrderFlowPlus() { SwingLookback = 20, TextOffsetTicks = 15, SignalFontSize = 13, DuplicateBarWindow = 5, ShowDisclaimer = false }, Input, ref orderflowplusCache);
				overnightgap = CacheIndicator<QI_OvernightGap>(new QI_OvernightGap() { LowerThreshold = -0.3, UpperThreshold = 0.3, ShowDisclaimer = false }, Input, ref overnightgapCache);
				rsi14 = CacheIndicator<QI_RSI14>(new QI_RSI14() { LowerThreshold = 40, UpperThreshold = 60, ShowDisclaimer = false }, Input, ref rsi14Cache);
				rsi2 = CacheIndicator<QI_RSI2>(new QI_RSI2() { LowerThreshold = 25, UpperThreshold = 75, ShowDisclaimer = false }, Input, ref rsi2Cache);
				rvzscore = CacheIndicator<QI_RVZScore>(new QI_RVZScore() { LowerThreshold = -1.5, UpperThreshold = 2.0, ShowDisclaimer = false }, Input, ref rvzscoreCache);
				sma200trend = CacheIndicator<QI_SMA200Trend>(new QI_SMA200Trend() { ShowDisclaimer = false }, Input, ref sma200trendCache);
				smc = CacheIndicator<QI_SMC>(new QI_SMC() { SwingLookback = 20, TextOffsetTicks = 15, SignalFontSize = 13, DuplicateBarWindow = 5, ShowDisclaimer = false }, Input, ref smcCache);
				stochfade = CacheIndicator<QI_StochFade>(new QI_StochFade() { LowerThreshold = 30, UpperThreshold = 70, ShowDisclaimer = false }, Input, ref stochfadeCache);
				turnaroundtuesday = CacheIndicator<QI_TurnaroundTuesday>(new QI_TurnaroundTuesday() { ShadeMonday = true, ShowDisclaimer = false }, Input, ref turnaroundtuesdayCache);
				turnofmonth = CacheIndicator<QI_TurnOfMonth>(new QI_TurnOfMonth() { ShadeWindow = true, ShowDisclaimer = false }, Input, ref turnofmonthCache);
				volumedelta = CacheIndicator<QI_VolumeDelta>(new QI_VolumeDelta() { ShowDisclaimer = false }, Input, ref volumedeltaCache);
				volumespike = CacheIndicator<QI_VolumeSpike>(new QI_VolumeSpike() { Threshold = 1.5, ShowDisclaimer = false }, Input, ref volumespikeCache);
				vrpproxy = CacheIndicator<QI_VRPProxy>(new QI_VRPProxy() { LowerThreshold = 0.7, UpperThreshold = 1.5, ShowDisclaimer = false }, Input, ref vrpproxyCache);
				vwapdistance = CacheIndicator<QI_VWAPDistance>(new QI_VWAPDistance() { LowerThreshold = -0.5, UpperThreshold = 0.5, ShowDisclaimer = false }, Input, ref vwapdistanceCache);
				widerangebar = CacheIndicator<QI_WideRangeBar>(new QI_WideRangeBar() { Threshold = 1.2, ShowDisclaimer = false }, Input, ref widerangebarCache);

				try
				{
					Directory.CreateDirectory(OutputFolder);
					string tf = BarsPeriod.BarsPeriodType + "-" + BarsPeriod.Value;
					string file = Path.Combine(OutputFolder, "qi_dump_" + Instrument.MasterInstrument.Name + "_" + tf + ".csv");
					writer = new StreamWriter(file, false);
					writer.WriteLine("BarTime,Bar,Open,High,Low,Close,Volume,QI_ATRRegime.Values[0],QI_ATRRegime.ATRRegime,QI_BollingerPctB.Values[0],QI_BollingerPctB.PctB,QI_ChopIndex.Values[0],QI_ChopIndex.Chop,QI_ChopIndex.ChoppyFlag,QI_ChopIndex.Adx,QI_ChopIndex.VolRatio,QI_CompositeVol.Values[0],QI_CompositeVol.CompositeVol,QI_CompositeVol.RVZScore,QI_CompositeVol.AtrChange,QI_ConnorsRSI.Values[0],QI_ConnorsRSI.CRSI,QI_ConnorsRSI.Streak,QI_ConsecDays.Values[0],QI_ConsecDays.Streak,QI_EMACross.Values[0],QI_EMACross.Values[1],QI_EMACross.Ema20,QI_EMACross.Ema50,QI_EMACross.Spread,QI_HedgingPressure.Values[0],QI_HedgingPressure.HPScore,QI_IBS.Values[0],QI_IBS.IBS,QI_LiquiditySweep.Values[0],QI_LiquiditySweep.Values[1],QI_LiquiditySweep.Confidence,QI_LiquiditySweep.Structure,QI_MACDHistogram.Values[0],QI_MACDHistogram.Histogram,QI_OrderFlowPlus.Values[0],QI_OrderFlowPlus.Values[1],QI_OrderFlowPlus.Confidence,QI_OrderFlowPlus.Structure,QI_OvernightGap.Values[0],QI_OvernightGap.GapPct,QI_RSI14.Values[0],QI_RSI14.RSI14,QI_RSI2.Values[0],QI_RSI2.RSI2,QI_RVZScore.Values[0],QI_RVZScore.RVZScore,QI_SMA200Trend.Values[0],QI_SMA200Trend.Sma200,QI_SMA200Trend.Distance,QI_SMC.Values[0],QI_SMC.Values[1],QI_SMC.Confidence,QI_SMC.Structure,QI_SMC.TrendDir,QI_StochFade.Values[0],QI_StochFade.Values[1],QI_StochFade.K,QI_StochFade.D,QI_TurnaroundTuesday.Values[0],QI_TurnaroundTuesday.DayOfWeekValue,QI_TurnOfMonth.Values[0],QI_TurnOfMonth.TurnOfMonth,QI_VolumeDelta.Values[0],QI_VolumeDelta.Values[1],QI_VolumeDelta.Values[2],QI_VolumeDelta.VolDelta,QI_VolumeDelta.CumDelta20,QI_VolumeDelta.DeltaSMA10,QI_VolumeSpike.Values[0],QI_VolumeSpike.VolumeSpike,QI_VRPProxy.Values[0],QI_VRPProxy.VRPProxy,QI_VWAPDistance.Values[0],QI_VWAPDistance.VwapDistance,QI_VWAPDistance.Vwap,QI_WideRangeBar.Values[0],QI_WideRangeBar.WideRange");
					writer.AutoFlush = true;
				}
				catch (Exception ex) { Print("QI_EgvDump init error: " + ex.Message); writer = null; }
			}
			else if (State == State.Terminated)
			{
				if (writer != null) { try { writer.Close(); } catch {} writer = null; }
			}
		}

		protected override void OnBarUpdate()
		{
			if (BarsInProgress != 0 || writer == null || CurrentBar < 50)
				return;
			try
			{
				var sb = new StringBuilder();
				sb.Append(Time[0].ToString("yyyy-MM-dd HH:mm:ss")).Append(',').Append(CurrentBar)
				  .Append(',').Append(Open[0].ToString("F4")).Append(',').Append(High[0].ToString("F4"))
				  .Append(',').Append(Low[0].ToString("F4")).Append(',').Append(Close[0].ToString("F4"))
				  .Append(',').Append(Volume[0].ToString("F0"));
				sb.Append(',').Append(Safe(atrregime.Values[0][0]));
				sb.Append(',').Append(Safe(atrregime.ATRRegime[0]));
				sb.Append(',').Append(Safe(bollingerpctb.Values[0][0]));
				sb.Append(',').Append(Safe(bollingerpctb.PctB[0]));
				sb.Append(',').Append(Safe(chopindex.Values[0][0]));
				sb.Append(',').Append(Safe(chopindex.Chop[0]));
				sb.Append(',').Append(Safe(chopindex.ChoppyFlag[0]));
				sb.Append(',').Append(Safe(chopindex.Adx[0]));
				sb.Append(',').Append(Safe(chopindex.VolRatio[0]));
				sb.Append(',').Append(Safe(compositevol.Values[0][0]));
				sb.Append(',').Append(Safe(compositevol.CompositeVol[0]));
				sb.Append(',').Append(Safe(compositevol.RVZScore[0]));
				sb.Append(',').Append(Safe(compositevol.AtrChange[0]));
				sb.Append(',').Append(Safe(connorsrsi.Values[0][0]));
				sb.Append(',').Append(Safe(connorsrsi.CRSI[0]));
				sb.Append(',').Append(Safe(connorsrsi.Streak[0]));
				sb.Append(',').Append(Safe(consecdays.Values[0][0]));
				sb.Append(',').Append(Safe(consecdays.Streak[0]));
				sb.Append(',').Append(Safe(emacross.Values[0][0]));
				sb.Append(',').Append(Safe(emacross.Values[1][0]));
				sb.Append(',').Append(Safe(emacross.Ema20[0]));
				sb.Append(',').Append(Safe(emacross.Ema50[0]));
				sb.Append(',').Append(Safe(emacross.Spread[0]));
				sb.Append(',').Append(Safe(hedgingpressure.Values[0][0]));
				sb.Append(',').Append(Safe(hedgingpressure.HPScore[0]));
				sb.Append(',').Append(Safe(ibs.Values[0][0]));
				sb.Append(',').Append(Safe(ibs.IBS[0]));
				sb.Append(',').Append(Safe(liquiditysweep.Values[0][0]));
				sb.Append(',').Append(Safe(liquiditysweep.Values[1][0]));
				sb.Append(',').Append(Safe(liquiditysweep.Confidence[0]));
				sb.Append(',').Append(Safe(liquiditysweep.Structure[0]));
				sb.Append(',').Append(Safe(macdhistogram.Values[0][0]));
				sb.Append(',').Append(Safe(macdhistogram.Histogram[0]));
				sb.Append(',').Append(Safe(orderflowplus.Values[0][0]));
				sb.Append(',').Append(Safe(orderflowplus.Values[1][0]));
				sb.Append(',').Append(Safe(orderflowplus.Confidence[0]));
				sb.Append(',').Append(Safe(orderflowplus.Structure[0]));
				sb.Append(',').Append(Safe(overnightgap.Values[0][0]));
				sb.Append(',').Append(Safe(overnightgap.GapPct[0]));
				sb.Append(',').Append(Safe(rsi14.Values[0][0]));
				sb.Append(',').Append(Safe(rsi14.RSI14[0]));
				sb.Append(',').Append(Safe(rsi2.Values[0][0]));
				sb.Append(',').Append(Safe(rsi2.RSI2[0]));
				sb.Append(',').Append(Safe(rvzscore.Values[0][0]));
				sb.Append(',').Append(Safe(rvzscore.RVZScore[0]));
				sb.Append(',').Append(Safe(sma200trend.Values[0][0]));
				sb.Append(',').Append(Safe(sma200trend.Sma200[0]));
				sb.Append(',').Append(Safe(sma200trend.Distance[0]));
				sb.Append(',').Append(Safe(smc.Values[0][0]));
				sb.Append(',').Append(Safe(smc.Values[1][0]));
				sb.Append(',').Append(Safe(smc.Confidence[0]));
				sb.Append(',').Append(Safe(smc.Structure[0]));
				sb.Append(',').Append(Safe(smc.TrendDir[0]));
				sb.Append(',').Append(Safe(stochfade.Values[0][0]));
				sb.Append(',').Append(Safe(stochfade.Values[1][0]));
				sb.Append(',').Append(Safe(stochfade.K[0]));
				sb.Append(',').Append(Safe(stochfade.D[0]));
				sb.Append(',').Append(Safe(turnaroundtuesday.Values[0][0]));
				sb.Append(',').Append(Safe(turnaroundtuesday.DayOfWeekValue[0]));
				sb.Append(',').Append(Safe(turnofmonth.Values[0][0]));
				sb.Append(',').Append(Safe(turnofmonth.TurnOfMonth[0]));
				sb.Append(',').Append(Safe(volumedelta.Values[0][0]));
				sb.Append(',').Append(Safe(volumedelta.Values[1][0]));
				sb.Append(',').Append(Safe(volumedelta.Values[2][0]));
				sb.Append(',').Append(Safe(volumedelta.VolDelta[0]));
				sb.Append(',').Append(Safe(volumedelta.CumDelta20[0]));
				sb.Append(',').Append(Safe(volumedelta.DeltaSMA10[0]));
				sb.Append(',').Append(Safe(volumespike.Values[0][0]));
				sb.Append(',').Append(Safe(volumespike.VolumeSpike[0]));
				sb.Append(',').Append(Safe(vrpproxy.Values[0][0]));
				sb.Append(',').Append(Safe(vrpproxy.VRPProxy[0]));
				sb.Append(',').Append(Safe(vwapdistance.Values[0][0]));
				sb.Append(',').Append(Safe(vwapdistance.VwapDistance[0]));
				sb.Append(',').Append(Safe(vwapdistance.Vwap[0]));
				sb.Append(',').Append(Safe(widerangebar.Values[0][0]));
				sb.Append(',').Append(Safe(widerangebar.WideRange[0]));
				writer.WriteLine(sb.ToString());
			}
			catch (Exception ex) { Print("QI_EgvDump row error at bar " + CurrentBar + ": " + ex.Message); }
		}

		private static string Safe(double v)
		{
			return (double.IsNaN(v) || double.IsInfinity(v)) ? "" : v.ToString("F4");
		}

		#region Properties
		[NinjaScriptProperty]
		[Display(Name = "Output Folder", Order = 1, GroupName = "Parameters")]
		public string OutputFolder { get; set; }
		#endregion
	}
}
